import { createSamlGw2ClientFromEnv } from "../samlgw2-client/index.mjs";

/**
 * Delete the samlgw2 customer created during tenant provisioning.
 */
export async function rollbackSamlGw2Customer(
  data,
  {
    createClient = createSamlGw2ClientFromEnv,
    logger = console,
  } = {},
) {
  const itorgId = data?.itorgId;
  const customer = data?.customer?.toLowerCase();

  if (!itorgId || !customer) {
    logger.warn("[ROLLBACK] Missing samlgw2 IT Org or customer, skipping");
    return;
  }

  try {
    const samlgw2 = createClient();
    await samlgw2.deleteCustomer(itorgId, customer);
    logger.info(
      `[ROLLBACK] Deleted samlgw2 customer '${customer}' from '${itorgId}'`,
    );
  } catch (error) {
    if (error.status === 404) {
      logger.info(
        `[ROLLBACK] samlgw2 customer '${customer}' is already absent`,
      );
      return;
    }
    throw error;
  }
}
